// Normalize the Vapi tool call into a flat shape for the router.
// n8n 2.x expression sandbox blocks reading .arguments on the payload,
// so we extract in a Code node instead of a Set node expression.
const toolCall = $input.first().json.body.message.toolCalls[0];
let toolArgs = {};
try {
  toolArgs = typeof toolCall.function.arguments === 'string'
    ? JSON.parse(toolCall.function.arguments)
    : (toolCall.function.arguments ?? {});
} catch (e) {
  // leave empty args; router will surface a missing-argument error
}
return [{
  toolCallId: toolCall.id,
  action: toolCall.function.name,
  toolArgs,
}];

const inv = $input.first()?.json;
/*
 * miniMustache — a dependency-free Mustache subset, embedded verbatim into the
 * n8n invoice-render Code nodes (n8n has no template engine and its sandbox
 * has no module system, so mustache.js's UMD wrapper is a liability here).
 *
 * Supported syntax (exactly what backend/templates/invoice.html uses):
 *   {{name}}        HTML-escaped value from the context stack
 *   {{{name}}}      raw value (no escaping)
 *   {{#key}}...{{/key}}  section: array -> loop (empty array renders nothing),
 *                        truthy -> render once with the value pushed,
 *                        falsy/missing (0, '', null, undefined) -> skip
 *   {{^key}}...{{/key}}  inverted section: renders only when the value is
 *                        falsy or an empty array
 * Names may use dotted paths (a.b.c). Unknown names render as ''.
 *
 * Node test harness: `node backend/templates/mustache_mini.test.js`
 * (exports via CommonJS when available; a plain function otherwise).
 */
function miniMustache(template, data) {
  // HTML comments never reach the output — and this template's own header
  // comment documents the syntax with literal {{...}} examples, so they must
  // not be tokenized.
  template = String(template).replace(/<!--[\s\S]*?-->/g, '');

  // Escape map built without literal entity text in the source.
  const AMP = String.fromCharCode(38);
  const ENT = {
    [String.fromCharCode(38)]: AMP + 'amp;',
    [String.fromCharCode(60)]: AMP + 'lt;',
    [String.fromCharCode(62)]: AMP + 'gt;',
    [String.fromCharCode(34)]: AMP + 'quot;',
    [String.fromCharCode(39)]: AMP + '#39;',
  };
  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ENT[c]);
  }

  function lookup(stack, name) {
    const parts = name.split('.');
    for (let i = stack.length - 1; i >= 0; i--) {
      let v = stack[i];
      let ok = true;
      for (const p of parts) {
        if (v == null || typeof v !== 'object' || !(p in v)) { ok = false; break; }
        v = v[p];
      }
      if (ok) return v;
    }
    return undefined;
  }

  function isTruthy(v) {
    if (Array.isArray(v)) return v.length > 0;
    return Boolean(v);
  }

  // tokenize: walk the template, producing text / tag tokens
  const tokens = [];
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{{', i);
    if (open === -1) { tokens.push({ t: 'text', v: template.slice(i) }); break; }
    if (open > i) tokens.push({ t: 'text', v: template.slice(i, open) });
    let raw = false, inner;
    if (template.slice(open, open + 3) === '{{{') {
      const close = template.indexOf('}}}', open + 3);
      if (close === -1) throw new Error('unterminated {{{ in template');
      inner = template.slice(open + 3, close);
      raw = true;
      i = close + 3;
    } else {
      const close = template.indexOf('}}', open + 2);
      if (close === -1) throw new Error('unterminated {{ in template');
      inner = template.slice(open + 2, close);
      i = close + 2;
    }
    const m = inner.match(/^\s*(#|\^|\/)?\s*([\w.]+)\s*$/);
    if (!m) throw new Error('bad tag: ' + inner);
    tokens.push({ t: m[1] || 'var', name: m[2], raw: raw });
  }

  // parse into a tree (sections nest)
  function parse(start, end) {
    const nodes = [];
    let i = start;
    while (i < end) {
      const tok = tokens[i];
      if (tok.t === 'text' || tok.t === 'var') { nodes.push(tok); i++; continue; }
      if (tok.t === '/') throw new Error('unexpected {{/' + tok.name + '}}');
      const close = tokens.findIndex((t, j) => j > i && t.t === '/' && t.name === tok.name);
      if (close === -1 || close >= end) throw new Error('unclosed section {{' + tok.t + tok.name + '}}');
      nodes.push({ t: tok.t, name: tok.name, body: parse(i + 1, close) });
      i = close + 1;
    }
    return nodes;
  }
  const tree = parse(0, tokens.length);

  function renderNodes(nodes, stack) {
    let out = '';
    for (const n of nodes) {
      if (n.t === 'text') { out += n.v; continue; }
      const v = lookup(stack, n.name);
      if (n.t === 'var') {
        const s = v == null ? '' : v;
        out += n.raw ? String(s) : escapeHtml(s);
      } else if (n.t === '#') {
        if (Array.isArray(v)) {
          for (const item of v) out += renderNodes(n.body, stack.concat([item]));
        } else if (isTruthy(v)) {
          out += renderNodes(n.body, stack.concat([v]));
        }
      } else if (n.t === '^') {
        if (!isTruthy(v)) out += renderNodes(n.body, stack);
      }
    }
    return out;
  }

  return renderNodes(tree, [data]);
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { render: miniMustache };
}

const INVOICE_TEMPLATE = "<!doctype html>\n<!--\n  INVOICE LAYOUT TEMPLATE \u2014 the single source of truth for what an invoice\n  looks like (the house rule: Render Invoice HTML in the gateway and the\n  approve-side fallback copy are BOTH generated from this file; never edit\n  them by hand). Format: Mustache (mustache.js, embedded by the patch script).\n\n  Data sources for each placeholder:\n    company_*      -> company_profile row (branding, addresses, GST/PST reg,\n                      payment_instructions) \u2014 per-company, multi-tenant ready\n    logo_data_uri  -> company_profile (logo_data + logo_content_type), built\n                      by the renderer as data:<type>;base64,<bytes> \u2014 so the\n                      archived invoice HTML is SELF-CONTAINED (an issued\n                      invoice never depends on an externally linked image).\n                      Empty = text-only header, the layout holds without it.\n    invoice_*      -> invoices row (number, type, dates, amounts, holdback)\n    bill_to_*      -> customer + structured bill-to address on the invoice\n    line_items     -> invoice_line_items rows (contract line / change orders),\n                      one table row each\n    holdback       -> invoices.holdback_amount + the dynamic holdback label\n    *_amount       -> always computed in SQL before rendering, never here\n\n  Mustache notes: sections are the list itself ({{#line_items}}), {{^name}}\n  is the \"unless\" branch. PDF remains print-to-PDF from this HTML\n  (@media print) \u2014 no server-side PDF engine.\n-->\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Invoice {{invoice_number}} \u2014 {{company_name}}</title>\n<style>\n  :root {\n    --brand: {{brand_primary_color}};\n    --ink: #0f172a;\n    --muted: #64748b;\n    --line: #e2e8f0;\n  }\n  * { box-sizing: border-box; }\n  body { font-family: -apple-system, 'Segoe UI', Roboto, Arial, sans-serif; color: var(--ink); margin: 0; }\n  .page { max-width: 800px; margin: 24px auto; padding: 32px 40px; }\n\n  header { display:flex; justify-content:space-between; align-items:flex-start;\n           border-bottom: 4px solid var(--brand); padding-bottom: 18px; }\n  .co { display: flex; align-items: center; gap: 16px; }\n  .logo { height: 56px; width: auto; border: 1px solid var(--line); border-radius: 8px;\n          padding: 4px; background: #fff; flex: none; }\n  .co h1 { font-size: 22px; margin: 0 0 4px; color: var(--brand); letter-spacing: .4px; }\n  .co p  { margin: 2px 0; color: var(--muted); font-size: 12px; line-height: 1.5; }\n  .doc { text-align: right; }\n  .doc .label { font-size: 26px; font-weight: 700; letter-spacing: 4px; }\n  .doc .num   { color: var(--brand); font-weight: 600; font-size: 15px; margin-top: 2px; }\n\n  .meta { display: flex; justify-content: space-between; gap: 32px; margin: 24px 0 6px; }\n  .meta h3 { font-size: 11px; text-transform: uppercase; letter-spacing: 1.2px;\n             color: var(--muted); margin: 0 0 6px; }\n  .meta p  { margin: 2px 0; font-size: 13px; line-height: 1.55; }\n  .meta .val { font-weight: 600; }\n\n  table.items { width: 100%; border-collapse: collapse; margin-top: 14px; }\n  .items th { text-align: left; font-size: 11px; text-transform: uppercase;\n              letter-spacing: 1.2px; color: var(--muted);\n              border-bottom: 2px solid var(--ink); padding: 8px 10px; }\n  .items td { padding: 12px 10px; font-size: 14px; border-bottom: 1px solid var(--line); }\n  .items .amt { text-align: right; white-space: nowrap; }\n\n  .totals { margin-left: auto; width: 320px; margin-top: 14px; }\n  .totals .row { display: flex; justify-content: space-between;\n                 padding: 6px 12px; font-size: 14px; }\n  .totals .row.grand { background: var(--brand); color: #fff; font-weight: 700;\n                       margin-top: 6px; border-radius: 3px; }\n  .totals .row.holdback { color: var(--muted); font-size: 13px; }\n\n  .pay { margin-top: 22px; background: #f1f5f9; border-left: 4px solid var(--brand);\n         padding: 14px 16px; font-size: 13px; line-height: 1.6; }\n  .pay strong { display: block; font-size: 11px; text-transform: uppercase;\n                letter-spacing: 1.2px; color: var(--muted); margin-bottom: 4px; }\n\n  footer { margin-top: 30px; border-top: 1px solid var(--line); padding-top: 12px;\n           font-size: 11px; color: var(--muted); text-align: center; line-height: 1.6; }\n\n  @media print {\n    .page { margin: 0; max-width: none; padding: 0; }\n    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n  }\n</style>\n</head>\n<body data-tpl=\"classic\">\n<div class=\"page\">\n\n  <header>\n    <div class=\"co\">\n      {{#logo_data_uri}}\n      <img class=\"logo\" src=\"{{logo_data_uri}}\" alt=\"{{company_name}} logo\">\n      {{/logo_data_uri}}\n      <div class=\"id\">\n        <h1>{{company_name}}</h1>\n        <p>{{company_address}}<br>\n           {{company_phone}}<br>\n           GST #: {{gst_reg_number}}<br>\n           PST #: {{pst_reg_number}}</p>\n      </div>\n    </div>\n    <div class=\"doc\">\n      <div class=\"label\">INVOICE</div>\n      <div class=\"num\">{{invoice_number}}</div>\n    </div>\n  </header>\n\n  <div class=\"meta\">\n    <div>\n      <h3>Bill To</h3>\n      <p><span class=\"val\">{{bill_to_name}}</span>{{#bill_to_address}}<br>\n         {{{bill_to_address}}}{{/bill_to_address}}</p>\n      <h3 style=\"margin-top:14px\">Project</h3>\n      <p>{{project_name}}</p>\n    </div>\n    <div style=\"text-align:right\">\n      <h3>Details</h3>\n      <p>Invoice date&nbsp;&nbsp;<span class=\"val\">{{issued_date}}</span><br>\n         Due date&nbsp;&nbsp;<span class=\"val\">{{due_date}}</span><br>\n         Type&nbsp;&nbsp;<span class=\"val\">{{invoice_type_label}}</span></p>\n    </div>\n  </div>\n\n  <table class=\"items\">\n    <tr><th style=\"width:32px\">#</th><th>Description</th><th class=\"amt\">Amount</th></tr>\n    {{#line_items}}\n    <tr><td>{{position}}</td>\n        <td>{{description}}</td>\n        <td class=\"amt\">{{amount}}</td></tr>\n    {{/line_items}}\n  </table>\n\n  <div class=\"totals\">\n    <div class=\"row\"><span>Subtotal</span><span>{{net_amount}}</span></div>\n    <div class=\"row\"><span>{{gst_label}}</span><span>{{gst_amount}}</span></div>\n    {{#pst_amount}}\n    <div class=\"row\"><span>PST</span><span>{{pst_amount}}</span></div>\n    {{/pst_amount}}\n    {{^pst_amount}}\n    <div class=\"row\"><span>PST</span><span>Not applicable</span></div>\n    {{/pst_amount}}\n    <div class=\"row grand\"><span>Total due</span><span>{{amount_due}}</span></div>\n    {{#holdback_amount}}\n    <div class=\"row holdback\"><span>{{holdback_label}}: {{holdback_amount}}</span></div>\n    {{/holdback_amount}}\n  </div>\n\n  {{#payment_instructions}}\n  <div class=\"pay\">\n    <strong>Payment instructions</strong>\n    {{{payment_instructions}}}\n  </div>\n  {{/payment_instructions}}\n\n  <footer>\n    {{company_name}} &bull; {{company_address}} &bull; {{company_phone}}<br>\n    Thank you for your business.\n  </footer>\n\n</div>\n</body>\n</html>\n";

function buildInvoiceData(inv) {
  const money = (v) => Number(v ?? 0).toLocaleString('en-CA', { style: 'currency', currency: 'CAD' });
  const typeMap = { 'DEPOSIT': 'Deposit', 'PROGRESS_BILLING': 'Progress billing',
                    'CHANGE_ORDER': 'Change order', 'FINAL': 'Final',
                    'Deposit': 'Deposit', 'Progress': 'Progress billing',
                    'Change Order': 'Change order', 'Final': 'Final' };
  const typeLabel = typeMap[inv?.invoice_type] || inv?.invoice_type || '';
  const addressLine = [inv?.street_address, inv?.city,
                       `${inv?.province ?? ''} ${inv?.postal_code ?? ''}`]
    .filter(Boolean).join(', ');
  const taxBits = [];  // (header reg lines are always rendered in the template)
  const lines = Array.isArray(inv?.lines) ? inv.lines : [];
  const pct = inv?.billing_percentage;
  const basis = inv?.billed_basis;
  const isOriginalBasis = pct != null && basis != null && inv?.contract_original != null &&
    Math.abs(Number(basis) - Number(inv.contract_original)) < 0.005;
  const basisLabel = isOriginalBasis ? 'contract value' : 'revised contract value';
  const lineLabel = inv?.description
    ? String(inv.description)
    : (pct != null && basis != null)
      ? `${typeLabel} \u2014 ${String(Number(pct))}% of ${basisLabel} (${money(basis)})`
      : typeLabel || 'Services';
  const billTo = [inv?.bill_street, inv?.bill_city,
                  inv?.bill_province ? `${inv?.bill_province} ${inv?.bill_postal ?? ''}` : inv?.bill_postal]
    .map(s => (s || '').toString().trim()).filter(Boolean).join('<br>');
  const holdbackPct = inv?.retention_rate != null
    ? Math.round(Number(inv.retention_rate) * 100) : 10;
  const items = lines.length
    ? lines.map((l, i) => ({ position: i + 1, description: l.description || '',
                             amount: money(l.amount) }))
    : [{ position: 1, description: lineLabel, amount: money(inv?.net_amount) }];
  const payLines = (inv?.payment_instructions || '').split('\n')
    .filter(s => s.trim().length > 0);
  return {
    brand_primary_color: inv?.brand_primary_color ?? '#1a3a5c',
    company_name: inv?.company_name ?? 'Ireh Construction',
    company_address: addressLine,
    company_phone: inv?.phone ?? '',
    // Header reg lines are ALWAYS on the layout (blank until the company
    // fills its registration numbers) — the user asked for reserved space.
    gst_reg_number: inv?.gst_reg_number ?? '',
    pst_reg_number: inv?.pst_reg_number ?? '',
    // The logo is baked in as a data: URI — an archived invoice never
    // depends on an externally linked image.
    logo_data_uri: inv?.logo_data && inv?.logo_content_type
      ? `data:${inv.logo_content_type};base64,${inv.logo_data}` : '',
    invoice_number: inv?.invoice_number ?? '',
    issued_date: inv?.issued_date ?? '',
    due_date: inv?.due_date ?? '',
    invoice_type_label: typeLabel,
    project_name: inv?.project_name ?? '',
    bill_to_name: (inv?.customer_name ?? '') +
                  (inv?.customer_company ? ' (' + inv.customer_company + ')' : ''),
    bill_to_address: billTo,
    line_items: items,
    net_amount: money(inv?.net_amount),
    gst_label: 'GST',
    // GST row is always on the layout ($0.00 when zero) — reserved space.
    gst_amount: money(inv?.gst_amount),
    // PST row is always on the layout: the amount, or "Not applicable".
    pst_amount: Number(inv?.pst_amount) ? money(inv.pst_amount) : 0,
    amount_due: money(inv?.amount_due),
    holdback_amount: Number(inv?.holdback_amount) ? money(inv.holdback_amount) : '',
    holdback_label: `Holdback (${holdbackPct}% retained)`,
    payment_instructions: payLines.join('<br>'),
  };
}
const html = miniMustache(inv.invoice_template_html || INVOICE_TEMPLATE, buildInvoiceData(inv));
return [{ json: { ...inv, invoiceHtml: html } }];

const r = $input.first()?.json;
const base = $env.PUBLIC_BASE_URL || 'https://n8n2.ordrnow.com';
const company = r?.company_name ?? 'Ireh Construction';
const accent = r?.brand_accent_color ?? '#2563eb';
const success = r?.brand_success_color ?? '#16a34a';
const link = `${base}/webhook/approve-estimate?token=${r?.token ?? ''}`;
const html = `<!doctype html><html><body style='font-family:Helvetica,Arial,sans-serif;color:#1e293b'><h2 style='color:${accent}'>Approve your estimate</h2><p>Hi ${r?.customer_name ?? ''}, please review and approve the baseline estimate for <strong>${r?.title ?? ''}</strong>.</p><p><a href='${link}' style='display:inline-block;padding:10px 16px;background:${success};color:#fff;text-decoration:none;border-radius:6px'>Review & approve</a></p><p style='color:#64748b;margin-top:24px'>${company}</p></body></html>`;
return [{ json: { ...r, html } }];

const r = $input.first()?.json;
const base = $env.PUBLIC_BASE_URL || 'https://n8n2.ordrnow.com';
const company = r?.company_name ?? 'Ireh Construction';
const accent = r?.brand_accent_color ?? '#2563eb';
const success = r?.brand_success_color ?? '#16a34a';
const link = `${base}/webhook/approve-change-order?token=${r?.token ?? ''}`;
const amount = Number(r?.cost_impact ?? 0);
const sign = amount >= 0 ? '+' : '';
const html = `<!doctype html><html><body style='font-family:Helvetica,Arial,sans-serif;color:#1e293b'><h2 style='color:${accent}'>Approve change order #${r?.change_order_number ?? ''}</h2><p>Hi ${r?.customer_name ?? ''}, please review and approve change order #${r?.change_order_number ?? ''} for <strong>${r?.project_name ?? ''}</strong>.</p><p>${r?.description ?? ''}: ${sign}$${Math.abs(amount).toLocaleString('en-US')}</p><p><a href='${link}' style='display:inline-block;padding:10px 16px;background:${success};color:#fff;text-decoration:none;border-radius:6px'>Review & approve</a></p><p style='color:#64748b;margin-top:24px'>${company}</p></body></html>`;
return [{ json: { ...r, html } }];

const toolCall = $('Normalize Tool Call').first().json;
const dbRow = $input.first()?.json;
const base = $env.PUBLIC_BASE_URL || 'https://n8n2.ordrnow.com';

let spoken = 'Done.';
switch (toolCall.action) {
  case 'lookup_or_create_customer': {
    const r = dbRow || {};
    if (r.outcome === 'CREATED') {
      spoken = `Customer ready - created ${r.name} (${r.email || 'no email'}).`;
    } else if (r.outcome === 'FOUND' && r.by_email) {
      spoken = `That email is already on file for ${r.name} (${r.email}) - I will use that customer. Anything else, like creating the project under ${r.name}?`;
    } else if (r.outcome === 'FOUND') {
      spoken = `Found existing customer ${r.name} (${r.email || 'no email'}).`;
    } else {
      spoken = 'I need the customer name and email address to add them.';
    }
    break;
  }
  case 'create_project': {
    const r = dbRow || {};
    if (r.outcome === 'CREATED') {
      spoken = `Project ${r.title} created for customer ${r.customer_name}.`;
    } else if (r.outcome === 'MISSING_TITLE') {
      spoken = 'What should the project be called?';
    } else {
      spoken = `I could not find a customer matching that name - use lookup_or_create_customer to add the customer first, or try find_customer to search.`;
    }
    break;
  }
  case 'create_estimate': {
    const r = dbRow || {};
    if (r.outcome === 'CREATED') {
      const total = Number(r.allocated_amount || 0).toLocaleString();
      spoken = `Baseline estimate recorded for ${r.project_title} at $${total}.`;
    } else if (r.outcome === 'MISSING_SCOPE') {
      spoken = 'What scope should the estimate cover?';
    } else {
      spoken = `I could not find project ${(toolCall.toolArgs && toolCall.toolArgs.project_id) || ''} - say the exact project name, or use list_projects to see what is on file.`;
    }
    break;
  }
  case 'find_customer': {
    const r = dbRow || {};
    if (r.matched) {
      const list = (r.candidates || []).map((c, i) =>
        `${i + 1}. ${c.name} (${c.email || 'no email'}) - ${c.label}, ${Math.round(c.score * 100)}%`).join('; ');
      spoken = `Closest matches for ${r.query}: ${list}`;
    } else {
      spoken = `No customers found matching ${r.query || 'that'}. Say a different name, or I can add a new customer with lookup_or_create_customer.`;
    }
    break;
  }
  case 'list_estimate_status': {
    const rows = $input.all().map(i => i.json).filter(r => r && r.project_name);
    if (!rows.length) { spoken = 'No estimates or projects match that status.'; }
    else {
      const lines = rows.map(r => {
        const st = r.baseline_status || 'NOT_SET';
        let when;
        if (st === 'APPROVED') when = ` approved ${r.baseline_approved_at ? String(r.baseline_approved_at).slice(0, 10) : ''} by ${r.baseline_approved_by || 'customer'}`;
        else if (st === 'REJECTED') when = ` rejected by the customer`;
        else if (st === 'SENT') when = ` sent for approval - awaiting customer decision`;
        else when = ` created - not yet sent for approval`;
        const ests = Number(r.est_count || 0) > 0
          ? `, ${r.est_count} estimate line${Number(r.est_count) === 1 ? '' : 's'} totaling $${Number(r.est_total || 0).toLocaleString()}`
          : ', no estimate lines yet';
        const last = r.last_kind ? ` (last ${r.last_kind}${r.last_at ? ' ' + String(r.last_at).slice(0, 16) : ''})` : '';
        return `${r.project_name} (${r.customer_name || ''}): baseline ${r.baseline_status || 'NOT_SET'}${when}${ests}${last}`;
      }).join(' ');
      spoken = lines;
    }
    break;
  }
  case 'create_change_order':
    spoken = dbRow && dbRow.id ? `Change order ${dbRow.change_order_number} recorded.` : 'Could not create change order - baseline estimate must be approved first.';
    break;
  case 'log_timesheet':
    spoken = dbRow && dbRow.id ? 'Hours logged.' : 'Worker not found - add the worker first.';
    break;
  case 'create_invoice':
    if (dbRow && dbRow.invoice_number && dbRow.invoice_type === 'CHANGE_ORDER') {
      spoken = `Draft invoice ${dbRow.invoice_number} created for $${Number(dbRow.amount_due).toLocaleString()} (incl. tax) - bills ${dbRow.line_count ?? 0} approved change order${dbRow.line_count === 1 ? '' : 's'} at full value${Number(dbRow.holdback_amount) > 0 ? `, with $${Number(dbRow.holdback_amount).toLocaleString()} holdback retained` : ''}. Want the preview pushed to your phone, or emailed to you?`;
    } else if (dbRow && dbRow.invoice_number) {
      spoken = `Draft invoice ${dbRow.invoice_number} created for $${Number(dbRow.amount_due).toLocaleString()} (incl. tax)${Number(dbRow.holdback_amount) > 0 ? `, with $${Number(dbRow.holdback_amount).toLocaleString()} holdback retained` : ''}. Want the preview pushed to your phone, or emailed to you?`;
    } else if (dbRow && dbRow.invoice_type === 'CHANGE_ORDER') {
      spoken = 'No unbilled approved change orders on this project - approve a change order first, or check the project name.';
    } else {
      spoken = 'Could not create the invoice - this billing percentage would exceed 100% of the contract value already billed, or the project was not found.';
    }
    break;
  case 'send_customer_invoice': {
    const row = $('Exec: send_customer_invoice_lookup').first().json;
    if (!row || !row.invoice_number) {
      spoken = 'Invoice not found. Ask the user to confirm the invoice number or project, then try again.';
    } else if (!row.email) {
      spoken = `Customer ${row.customer_name} has no email address on file. Ask the user for the client's email, call update_customer to set the client email, then retry sending the invoice.`;
    } else {
      const wasSent = row.email_sent_at
        ? ` This invoice was already sent to the client on ${String(row.email_sent_at).slice(0, 10)} - approving again will resend it.`
        : '';
      spoken = `Preview emailed to you at ${row.email_from || 'your inbox'}. Review it there and tap Approve to send it to ${row.customer_name}, or Reject to cancel.${wasSent}`;
    }
    break;
  }
  case 'get_project_statement':
    spoken = dbRow && dbRow.project_name
      ? `${dbRow.project_name} (${dbRow.customer_name}): Revised contract is $${Number(dbRow.total_revised_contract_value).toLocaleString()}, $${Number(dbRow.total_paid).toLocaleString()} collected. Outstanding balance is $${Number(dbRow.balance_remaining).toLocaleString()}.`
      : 'Project not found.';
    break;
  case 'get_estimate_approval_link': {
    const row = $('Exec: get_estimate_approval_link').first().json;
    if (!row || !row.id) {
      spoken = 'Project not found.';
    } else if (row.already_approved) {
      const when = row.baseline_approved_at ? ' on ' + String(row.baseline_approved_at).slice(0, 10) : '';
      const who = row.baseline_approved_by ? (' by ' + row.baseline_approved_by) : '';
      spoken = `${row.title} is already approved${who}${when} - no approval link needed.`;
    } else if (dbRow && Number(dbRow.pushed) > 0) {
      spoken = `Approval link for ${row.title} sent to your phone - the customer can tap it to sign.`;
    } else {
      spoken = `Approval link ready: ${base}/webhook/approve-estimate?token=${row.approval_token}`;
    }
    break;
  }
  case 'get_change_order_approval_link': {
    const row = $('Exec: get_change_order_approval_link').first().json;
    if (!row || !row.approval_token) {
      spoken = 'Change order not found.';
    } else if (dbRow && Number(dbRow.pushed) > 0) {
      spoken = `Approval link for ${row.project_name} change order ${row.change_order_number} sent to your phone - tap the notification to open it.`;
    } else {
      spoken = `Approval link ready: ${base}/webhook/approve-change-order?token=${row.approval_token}`;
    }
    break;
  }
  case 'send_estimate_for_approval': {
    const row = $('Exec: send_estimate_for_approval_lookup').first().json;
    if (row && row.block_reason === 'ALREADY_APPROVED') {
      const when = row.baseline_approved_at ? ' on ' + String(row.baseline_approved_at).slice(0, 10) : '';
      const who = row.baseline_approved_by ? (' by ' + row.baseline_approved_by) : '';
      spoken = `${row.title || 'This project'} is already approved${who}${when} - no approval link needed.`;
    } else if (row && row.block_reason === 'NO_EMAIL') {
      spoken = 'The client has no email address on file. Ask the user for it, call update_customer to set the email, then retry.';
    } else if (!row || !row.id || row.block_reason === 'NOT_FOUND') {
      spoken = 'Project or customer not found.';
    } else {
      spoken = 'Approval link emailed to the client - waiting on their signature.';
    }
    break;
  }
  case 'send_change_order_for_approval': {
    const row = $('Exec: send_change_order_for_approval_lookup').first().json;
    if (!row || !row.email) {
      spoken = row ? 'The client has no email address on file. Ask the user for it, call update_customer to set the email, then retry.' : 'Change order not found.';
    } else {
      spoken = 'Change order approval link emailed to the client.';
    }
    break;
  }
  case 'update_customer': {
    const bits = [];
    if (dbRow && dbRow.email) bits.push(`email ${dbRow.email}`);
    if (dbRow && dbRow.phone) bits.push(`phone ${dbRow.phone}`);
    if (dbRow && (dbRow.street_address || dbRow.city)) {
      bits.push(`address ${[dbRow.street_address, dbRow.city, dbRow.province].filter(Boolean).join(', ')}${dbRow.postal_code ? ' ' + dbRow.postal_code : ''}`);
    }
    spoken = !dbRow || dbRow.outcome === 'NOT_FOUND'
      ? `No customer named ${(toolCall.toolArgs && toolCall.toolArgs.customer_id) || ''} is on file - call find_customer to search close matches, or add them with lookup_or_create_customer.`
      : dbRow.outcome === 'INVALID_EMAIL'
        ? 'That does not look like a valid email address. Please ask the user for a correct address, then call update_customer again.'
        : bits.length ? `Customer ${dbRow.name} updated - ${bits.join(', ')}.` : 'Customer updated.';
    break;
  }
  case 'update_company_billing':
    spoken = dbRow
      ? `Company billing details updated${dbRow.gst_reg_number ? ` - GST number ${dbRow.gst_reg_number}` : ''}.`
      : 'Could not update company billing details.';
    break;
    case 'record_payment':
    spoken = dbRow && dbRow.invoice_number
      ? `Payment recorded. ${dbRow.invoice_number} is now ${(dbRow.status || '').toLowerCase()}; balance due $${Number(dbRow.balance_due).toLocaleString()}. Want me to email a receipt to the customer?`
      : 'Invoice not found.';
    break;
  case 'send_payment_receipt': {
    const row = $('Exec: receipt_lookup').first().json;
    if (!row || !row.invoice_number) {
      spoken = 'Invoice not found. Ask the user to confirm the invoice number, then try again.';
    } else if (!row.has_email) {
      spoken = `Customer ${row.customer_company || row.customer_name} has no email address on file. Ask the user for the client's email, call update_customer to set it, then retry sending the receipt.`;
    } else if (!row.has_payments) {
      spoken = `There are no payments recorded on ${row.invoice_number} yet, so there is nothing to receipt.`;
    } else if (dbRow && dbRow.id) {
      const paidInFull = Number(row.balance_due) <= 0;
      spoken = `Receipt emailed to ${row.customer_company || row.customer_name} at ${row.customer_email}: $${Number(row.latest_amount).toLocaleString()} received${row.latest_method ? ' by ' + row.latest_method : ''}${paidInFull ? ' - this invoice is now paid in full.' : ` - balance remaining $${Number(row.balance_due).toLocaleString()}.`}`;
    } else {
      spoken = 'Could not send the receipt - please try again.';
    }
    break;
  }
  case 'send_invoice_to_phone': {
    const row = $('Exec: invoice_push_lookup').first().json;
    if (!row || !row.invoice_number) {
      spoken = 'Invoice not found. Ask the user to confirm the invoice number or project, then try again.';
    } else if (!row.email) {
      spoken = `Customer ${row.customer_company || row.customer_name} has no email address on file. Ask the user for the client's email, call update_customer to set it, then push the invoice again.`;
    } else if (dbRow && Number(dbRow.pushed) > 0) {
      spoken = `Invoice ${row.invoice_number} pushed to your phone - View to review it, or tap Approve to send it to ${row.customer_company || row.customer_name}.`;
    } else {
      spoken = `No registered phone to push to - say you want it emailed instead, and I will send the preview to your inbox.`;
    }
    break;
  }

  case 'run_payroll':
    spoken = dbRow && dbRow.run_id
      ? `Payroll computed for ${dbRow.period_start} to ${dbRow.period_end}: ${dbRow.workers} worker(s), $${Number(dbRow.gross_pay).toLocaleString()} gross, $${Number(dbRow.net_pay).toLocaleString()} net.`
      : 'No timesheets found for that period.';
    break;
  case 'get_payroll_summary':
    spoken = dbRow && dbRow.run_id
      ? `Payroll for ${dbRow.period_start} to ${dbRow.period_end}: $${Number(dbRow.gross_pay).toLocaleString()} gross, $${Number(dbRow.net_pay).toLocaleString()} net (${dbRow.workers} workers).`
      : 'No payroll run found.';
    break;
  case 'add_worker':
    spoken = dbRow && dbRow.worker_code
      ? `Worker ${dbRow.name} added as ${dbRow.worker_code}${dbRow.trade ? ' (' + dbRow.trade + ')' : ''}.`
      : 'Could not add worker.';
    break;
  case 'get_dashboard_summary': {
    const rows = $input.all().map(i => i.json);
    if (!rows.length) { spoken = 'No projects found.'; }
    else {
      spoken = rows.map(r => `${r.project_name}: contract $${Number(r.total_revised_contract_value).toLocaleString()}, paid $${Number(r.total_paid).toLocaleString()}, balance $${Number(r.balance_remaining).toLocaleString()}.`).join(' ');
    }
    break;
  }
  case 'list_projects': {
    const rows = $input.all().map(i => i.json).filter(r => r && r.project_name);
    if (!rows.length) { spoken = 'No projects found.'; }
    else {
      spoken = rows.map(r => `${r.project_name} (${r.project_status}): contract $${Number(r.total_revised_contract_value).toLocaleString()}, paid $${Number(r.total_paid).toLocaleString()}, balance $${Number(r.balance_remaining).toLocaleString()}.`).join(' ');
    }
    break;
  }
  case 'list_invoices': {
    const rows = $input.all().map(i => i.json).filter(r => r && r.invoice_number);
    if (!rows.length) { spoken = 'No invoices found.'; }
    else {
      // Totals are computed here in the code node (deterministic) — never
      // left to the LLM to sum formatted money.
      const totalOut = rows.reduce((s, r) => s + Number(r.balance_due || 0), 0);
      const one = rows.map(r => `${r.invoice_number} ${r.project_name}: $${Number(r.amount_due).toLocaleString()} (${r.status}), balance $${Number(r.balance_due).toLocaleString()}.`).join(' ');
      spoken = `${rows.length} invoice${rows.length === 1 ? '' : 's'} totaling $${totalOut.toLocaleString()}: ${one}`;
    }
    break;
  }
  case 'get_schedule': {
    const rows = $input.all().map(i => i.json).filter(r => r && r.title);
    if (!rows.length) { spoken = 'Nothing scheduled in that window.'; }
    else {
      spoken = rows.map(r => {
        let when = 'no date';
        if (r.due_date) {
          const parts = String(r.due_date).slice(0, 10).split('-').map(Number);
          if (parts.length === 3 && parts.every(n => !isNaN(n))) {
            const due = new Date(parts[0], parts[1] - 1, parts[2]);
            const now = new Date(); now.setHours(0, 0, 0, 0);
            const diff = Math.round((due - now) / 86400000);
            when = diff < 0 ? (Math.abs(diff) + ' days overdue') : diff === 0 ? 'today' : diff === 1 ? 'tomorrow' : ('in ' + diff + ' days');
          }
        }
        return `${r.title} ${when}${r.project_name ? ' (' + r.project_name + ')' : ''}`;
      }).join('. ');
    }
    break;
  }
  case 'set_briefing_time': {
    spoken = dbRow && dbRow.briefing_time ? `Daily briefing set to ${String(dbRow.briefing_time).slice(0, 5)}.` : 'Could not update briefing time.';
    break;
  }
  case 'get_onboarding_status':
    spoken = dbRow && dbRow.setup_completed
      ? `Setup is complete. ${dbRow.company_name}, ${dbRow.worker_count} active worker${dbRow.worker_count === 1 ? '' : 's'} on file. Invoices use the ${dbRow.invoice_template || 'classic'} style.`
      : 'Setup is not complete yet. Let us start - what is the company name?';
    break;
  case 'complete_onboarding':
    spoken = dbRow && dbRow.company_name
      ? `All set, ${dbRow.pm_preferred_name || 'boss'}. ${dbRow.company_name} is registered with ${dbRow.worker_count} worker${dbRow.worker_count === 1 ? '' : 's'} on file, invoices set to the ${dbRow.invoice_template || 'classic'} style. Anything else?`
      : 'Setup did not complete. Please try again.';
    break;
  case 'remove_project': {
    const r = dbRow || {};
    if (r.outcome === 'REMOVED') {
      spoken = `Removed ${r.title}. It is hidden from every list and tool; the invoices, estimates and change orders stay on file.`;
    } else if (r.outcome === 'NEEDS_CONFIRMATION') {
      const inv = Number(r.invoices || 0), est = Number(r.estimates || 0), co = Number(r.change_orders || 0);
      const parts = [];
      if (inv) parts.push(`${inv} invoice${inv === 1 ? '' : 's'}`);
      if (est) parts.push(`${est} estimate${est === 1 ? '' : 's'}`);
      if (co) parts.push(`${co} change order${co === 1 ? '' : 's'}`);
      const attached = parts.length ? `It has ${parts.join(', ')} attached` : 'Nothing is attached to it';
      spoken = `${attached}. Removing ${r.title} hides the project from every tool - the records stay on file. Should I remove it?`;
    } else {
      spoken = `I could not find an active project called ${(toolCall.toolArgs && toolCall.toolArgs.project) || 'that'} - it may already be removed.`;
    }
    break;
  }
  case 'list_invoice_templates': {
    const r = dbRow || {};
    const list = Array.isArray(r.templates) ? r.templates : [];
    const names = list.map((t) => `${t.name} (${t.key})`).join('; ');
    const cur = r.current_key || 'classic';
    if (r.note === 'no registered devices' || (r.note || '').indexOf('not configured') !== -1) {
      spoken = `Your invoices use the ${cur} style. The others: ${names}. I could not push the preview to a phone - preview link: ${r.preview_url || ''}`;
    } else {
      spoken = `Your invoices use the ${cur} style. Available: ${names}. I sent the styles to your phone - swipe to compare them side by side and tap to choose.`;
    }
    break;
  }
  case 'set_invoice_template': {
    const r = dbRow || {};
    spoken = r.outcome === 'UPDATED'
      ? `Done - invoices now use the ${r.template} style.`
      : 'That is not one of the invoice styles. Say classic, modern or compact - or ask me to list the styles.';
    break;
  }
  default:
    spoken = `I'm not sure how to handle "${toolCall.action}". Please rephrase, or ask for something like project status, estimates, invoices, payments, or payroll.`;
}

return [{
  json: {
    toolCallId: toolCall.toolCallId,
    result: spoken,
  },
}];

// Push Briefing Time Change (runs after set_briefing_time UPDATE + get_device_tokens).
// Sends an FCM data message {type:"briefing_time_changed", briefing_time} to every
// registered device so the app re-schedules its local notification (no tap needed).
// Key sources (in order): FCM_SERVICE_ACCOUNT_FILE (mounted secrets file) or
// FCM_SERVICE_ACCOUNT_JSON (single-line env). Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto,fs,https
// (n8n 2.35 task-runner allowlist env; $helpers does NOT exist in 2.35 Code nodes).
const briefingTime = String($('Exec: set_briefing_time').first().json.briefing_time || '').slice(0, 5);
const tokens = $input.all().map(i => i.json).filter(r => r && r.token).map(r => r.token);
let saRaw = String($env.FCM_SERVICE_ACCOUNT_JSON || '').trim();
let keyNote = '';
if (!saRaw) {
  try {
    const file = String($env.FCM_SERVICE_ACCOUNT_FILE || '').trim();
    if (file) saRaw = require('fs').readFileSync(file, 'utf8').trim();
  } catch (e) {
    keyNote = 'FCM key file read failed: ' + e.message;
  }
}

let pushed = 0;
let note = keyNote || 'FCM not configured (FCM_SERVICE_ACCOUNT_JSON/FILE unset); push skipped';
if (!saRaw) {
  // no key — note already explains (unset or file read failure)
} else if (tokens.length === 0) {
  note = 'no registered devices';
} else {
  try {
    const sa = JSON.parse(saRaw);
    const crypto = require('crypto');
    const accessToken = await getAccessToken(sa, crypto);
    for (const token of tokens) {
      await sendFcm(accessToken, sa.project_id, token, { type: 'briefing_time_changed', briefing_time: briefingTime });
      pushed++;
    }
    note = 'pushed to ' + pushed + ' device(s)';
  } catch (e) {
    note = 'FCM send failed: ' + e.message;
  }
}

return [{ json: { briefing_time: briefingTime, pushed, note } }];

function b64url(s) {
  return s.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function splitUrl(u) {
  const m = u.match(/^https?:\/\/([^/]+)(\/[^?#]*)?(\?[^#]*)?/);
  return { hostname: m[1], path: (m[2] || '/') + (m[3] || '') };
}

function httpsRequest(options, body) {
  return new Promise((resolve, reject) => {
    const req = require('https').request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function getAccessToken(sa, crypto) {
  const now = Math.floor(Date.now() / 1000);
  const head = b64url(Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64'));
  const claim = b64url(Buffer.from(JSON.stringify({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/firebase.messaging',
    aud: sa.token_uri,
    iat: now,
    exp: now + 3600
  })).toString('base64'));
  const input = head + '.' + claim;
  const sig = b64url(crypto.createSign('RSA-SHA256').update(input).sign(sa.private_key).toString('base64'));
  const jwt = input + '.' + sig;
  const u = splitUrl(sa.token_uri);
  const resp = await httpsRequest({
    method: 'POST',
    hostname: u.hostname,
    path: u.path,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  }, 'grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=' + encodeURIComponent(jwt));
  const parsed = JSON.parse(resp.body);
  if (!parsed.access_token) {
    throw new Error('token exchange failed (' + resp.status + '): ' + resp.body.slice(0, 200));
  }
  return parsed.access_token;
}

async function sendFcm(accessToken, projectId, token, data) {
  const u = splitUrl('https://fcm.googleapis.com/v1/projects/' + projectId + '/messages:send');
  const resp = await httpsRequest({
    method: 'POST',
    hostname: u.hostname,
    path: u.path,
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + accessToken },
  }, JSON.stringify({ message: { token, data } }));
  if (resp.status >= 400) {
    throw new Error('FCM HTTP ' + resp.status + ': ' + resp.body.slice(0, 200));
  }
}

const inv = $input.first()?.json;
