// Fuzzy best-match over the company's customers (option B: code-node scoring).
// Labels: 'exact' / 'email' / 'phone' / 'close match' / 'possible match'.
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, ' ');
const toks = (s) => norm(s) ? norm(s).split(' ') : [];
const bigrams = (s) => { const b = new Set(); for (let i = 0; i < s.length - 1; i++) b.add(s.slice(i, i + 2)); return b; };
const bigramSim = (a, b) => {
  if (a.length < 4 || b.length < 4) return 0;
  const A = bigrams(a), B = bigrams(b);
  let hit = 0; for (const x of A) if (B.has(x)) hit++;
  const denom = (A.size + B.size) / 2;
  return denom ? hit / denom : 0;
};
const args = $('Normalize Tool Call').first().json.toolArgs || {};
const qName = norm(args.name || '');
const qEmail = norm(args.email || '');
const qPhone = String(args.phone || '').replace(/\D/g, '');
const want = qName || qEmail || qPhone;
const rows = $input.all();
const scored = [];
for (const it of rows) {
  const r = it.json;
  const name = r.name || '';
  let score = 0, label = '';
  const nName = norm(name);
  const phone = String(r.phone || '').replace(/\D/g, '');
  const emailOk = qEmail && norm(r.email || '') === qEmail;
  const phoneOk = qPhone && phone && qPhone.length >= 7 && (phone.endsWith(qPhone) || qPhone.endsWith(phone));
  if (emailOk) { score = 1; label = 'email match'; }
  else if (phoneOk) { score = 1; label = 'phone match'; }
  else if (qName) {
    if (nName === qName) { score = 1; label = 'exact'; }
    else if (nName && (nName.includes(qName) || qName.includes(nName))) {
      score = 0.85; label = 'close match';
    } else {
      const nt = toks(name), qt = toks(qName);
      let sum = 0;
      for (const q of qt) {
        let best = 0;
        for (const t of nt) {
          if (t === q) best = Math.max(best, 1);
          else if (t.startsWith(q) || q.startsWith(t)) best = Math.max(best, 0.6);
          else if (t.includes(q) || q.includes(t)) best = Math.max(best, 0.5);
          else best = Math.max(best, bigramSim(q, t) * 0.7);
        }
        sum += best;
      }
      if (qt.length) score = (sum / qt.length) * 0.9;
      label = score >= 0.6 ? 'close match' : 'possible match';
    }
  }
  if (want && score >= 0.45) {
    scored.push({ id: r.id, name, email: r.email || '', phone: r.phone || '',
                  score: Math.round(score * 100) / 100, label });
  }
}
scored.sort((a, b) => b.score - a.score);
const top = scored.slice(0, 3);
return [{ json: { matched: top.length > 0, query: args.name || args.email || args.phone || '',
                  candidates: top } }];

// Push the invoice-style preview page (side-by-side, tap-to-choose) to every
// registered phone: data {type:'open_url', url, title, body}. Same FCM
// helpers as Push Invoice Review, wrapped in an async run() so node --check
// passes (no top-level await in the source).
async function run() {
  const crypto = require('crypto');
  const row = $('Exec: list_invoice_templates').first().json;
  const base = $env.PUBLIC_BASE_URL || 'https://n8n2.ordrnow.com';
  const secret = $env.AUTH_TOKEN_SECRET || '';
  const company = '1';
  const exp = Math.floor(Date.now() / 1000) + 7 * 86400;
  const sig = crypto.createHmac('sha256', secret).update(`${company}.template-preview.${exp}`).digest('base64url');
  const previewUrl = `${base}/webhook/invoice-template-preview?company=${company}&exp=${exp}&sig=${encodeURIComponent(sig)}`;
  const title = 'Invoice styles';
  const body = 'Compare Classic, Modern and Compact side by side, then tap to choose.';
  const tokens = $input.all().map(i => i.json).filter(r => r && r.token).map(r => r.token);
  let saRaw = String($env.FCM_SERVICE_ACCOUNT_JSON || '').trim();
  let note = '';
  if (!saRaw) {
    try {
      const file = String($env.FCM_SERVICE_ACCOUNT_FILE || '').trim();
      if (file) saRaw = require('fs').readFileSync(file, 'utf8').trim();
    } catch (e) { note = 'FCM key file read failed: ' + e.message; }
  }
  let pushed = 0;
  if (!saRaw) note = note || 'FCM not configured; push skipped';
  else if (tokens.length === 0) note = 'no registered devices';
  else {
    try {
      const sa = JSON.parse(saRaw);
      const accessToken = await getAccessToken(sa, crypto);
      let stale = 0;
      for (const token of tokens) {
        try { await sendFcm(accessToken, sa.project_id, token, { type: 'open_url', url: previewUrl, title, body }); pushed++; }
        catch (e) { stale++; }
      }
      note = 'pushed to ' + pushed + ' device(s)' + (stale ? ', ' + stale + ' stale' : '');
    } catch (e) { note = 'FCM send failed: ' + e.message; }
  }
  return { ...row, preview_url: previewUrl, pushed, note };
}
return run().then((r) => [{ json: r }]);

